--
-- Table structure for table `point_template`
--

DROP TABLE IF EXISTS `point_template`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `point_template` (
  `point_tmpl_id` bigint NOT NULL AUTO_INCREMENT COMMENT '点位模板ID',
  `device_tmpl_id` bigint NOT NULL COMMENT '关联设备模板的ID',
  `alarm_code` varchar(200) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_as_cs DEFAULT NULL COMMENT '报警策略(关联alarm表的alarm_name字段)。例如：Communication_status_00',
  `point_name` varchar(150) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_as_cs NOT NULL COMMENT '点位名',
  `point_type` varchar(10) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_as_cs DEFAULT NULL COMMENT '点位类型：DI|DO|AI|AO',
  `data_type` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_as_cs NOT NULL COMMENT '点位的数据类型：numeric|enum|boolean|string',
  `unit` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_as_cs DEFAULT NULL COMMENT '单位',
  `display_precision` tinyint DEFAULT NULL COMMENT '显示精度：0/1/2/3/4（小数位数）',
  `is_deleted` tinyint(1) NOT NULL DEFAULT '0' COMMENT '逻辑删除标记',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  PRIMARY KEY (`point_tmpl_id`) USING BTREE,
  UNIQUE KEY `uk_tmpl_point_name` (`point_name`) USING BTREE COMMENT '点位模板名唯一（模板名中已包含设备模板名）',
  KEY `idx_device_tmpl_id` (`device_tmpl_id`) USING BTREE,
  KEY `idx_alarm_code` (`alarm_code`) USING BTREE
) ENGINE=InnoDB AUTO_INCREMENT=557 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_as_cs ROW_FORMAT=DYNAMIC COMMENT='模板点位表';
/*!40101 SET character_set_client = @saved_cs_client */;

--
-- Dumping data for table `point_template`
--

LOCK TABLES `point_template` WRITE;
/*!40000 ALTER TABLE `point_template` DISABLE KEYS */;
