--
-- Table structure for table `point_deployment`
--

DROP TABLE IF EXISTS `point_deployment`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `point_deployment` (
  `point_deploy_id` bigint NOT NULL AUTO_INCREMENT COMMENT '点位ID',
  `point_tmpl_id` bigint NOT NULL COMMENT '关联点位模板ID',
  `device_deploy_id` bigint NOT NULL COMMENT '关联部署设备ID',
  `alarm_code` varchar(200) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_as_cs DEFAULT NULL COMMENT '报警策略(关联alarm表的alarm_name字段)。例如：Communication_status_00',
  `point_name` varchar(150) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_as_cs NOT NULL COMMENT '点位名，例：A1_MVP_A1_Collector_DO1_1',
  `n4_address` varchar(200) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_as_cs NOT NULL COMMENT 'topic路径，例：/Drivers/ModbusTcpNetwork/A1_MVP_A1/points/A1_MVP_A1_Collector/DO1_1',
  `point_code` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_as_cs DEFAULT NULL COMMENT '点位编码（暂时保留），如：4810005',
  `register` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_as_cs DEFAULT NULL COMMENT '寄存器地址（暂时保留）',
  `point_type` varchar(10) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_as_cs DEFAULT NULL COMMENT '点位类型：DI|DO|AI|AO',
  `data_type` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_as_cs NOT NULL COMMENT '点位的数据类型：numeric|enum|boolean|string',
  `unit` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_as_cs DEFAULT NULL COMMENT '单位',
  `display_precision` tinyint DEFAULT '0' COMMENT '显示精度：0/1/2/3/4（小数位数）',
  `is_deleted` tinyint(1) NOT NULL DEFAULT '0' COMMENT '逻辑删除标记',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  PRIMARY KEY (`point_deploy_id`) USING BTREE,
  UNIQUE KEY `uk_deploy_point_name` (`point_name`) USING BTREE COMMENT '点位部署名唯一（部署名中已包含设备部署名）',
  KEY `idx_point_tmpl_id` (`point_tmpl_id`) USING BTREE,
  KEY `idx_device_deploy_id` (`device_deploy_id`) USING BTREE,
  KEY `idx_alarm_code` (`alarm_code`) USING BTREE,
  KEY `idx_n4_address` (`n4_address`) USING BTREE
) ENGINE=InnoDB AUTO_INCREMENT=2477 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_as_cs ROW_FORMAT=DYNAMIC COMMENT='监控点位表';
/*!40101 SET character_set_client = @saved_cs_client */;

